mapper.select:
select distinct t2.user_id user_id, t2.user_name, t2.login_name, t2.gender from bp_user_dept t1 join bp_user t2 on t1.user_id=t2.user_id where t1.is_deleted = 0 and t2.is_deleted=0
and t1.dept_id= #{deptId}
and t2.user_name like concat('%',#{userName},'%')

select id
from bp_dept
where is_deleted = 0
and dept_name = #{deptName}

    and id!=#{id}
